package com.hiretrack.controller;import com.hiretrack.repository.ApplicationRepository;import com.hiretrack.service.CurrentUser;import org.springframework.web.bind.annotation.*;import java.time.*;import java.time.format.TextStyle;import java.util.*;@RestController @RequestMapping("/api")public class DashboardController{private final ApplicationRepository repo;private final CurrentUser current;public DashboardController(ApplicationRepository r,CurrentUser c){repo=r;current=c;}private long count(String s){return repo.countByUserIdAndStatus(current.get().getId(),s);}@GetMapping("/dashboard/stats")public Map<String,Object> stats(){long total=repo.countByUserId(current.get().getId()),offer=count("OFFER"),reject=count("REJECTED"),wish=count("WISHLIST"),withdraw=count("WITHDRAWN"),active=Math.max(0,total-offer-reject-wish-withdraw),reached=count("INTERVIEW")+offer;List<Map<String,Object>> by=List.of("WISHLIST","APPLIED","ASSESSMENT","INTERVIEW","OFFER","REJECTED","WITHDRAWN").stream().map(s->Map.<String,Object>of("status",s,"count",count(s))).toList();return Map.of("totalApplications",total,"activeApplications",active,"upcomingInterviews",0,"offers",offer,"interviewConversion",total==0?0:Math.round(reached*1000.0/total)/10.0,"offerConversion",total==0?0:Math.round(offer*1000.0/total)/10.0,"byStatus",by);}
@GetMapping("/analytics/monthly")public List<Map<String,Object>> monthly(){var all=repo.findAllByUserIdOrderByCreatedAtDesc(current.get().getId());List<Map<String,Object>> out=new ArrayList<>();YearMonth now=YearMonth.now();for(int i=5;i>=0;i--){YearMonth ym=now.minusMonths(i);long n=all.stream().filter(a->a.getAppliedDate()!=null&&YearMonth.from(a.getAppliedDate()).equals(ym)).count();out.add(Map.of("month",ym.getMonth().getDisplayName(TextStyle.SHORT,Locale.ENGLISH),"applications",n));}return out;}}